<?php
$appPage='credit';$appTitle='Credit center';require __DIR__.'/../includes/customer_header.php';$service=new CreditService($pdo);$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$action=$_POST['action']??'';if($action==='apply'){$id=$service->apply($customerId,Money::fromDecimal($_POST['amount']??''),(int)($_POST['term_months']??0),$_POST['purpose']??'');$success='Application '.$id.' was submitted for review.';}elseif($action==='accept'){$result=$service->acceptAndDisburse($customerId,(int)$_POST['application_id'],$_POST['idempotency_key']??'');$success='Credit accepted and disbursed. Reference '.$result['reference'].'.';}elseif($action==='repay'){$result=$service->repay($customerId,(int)$_POST['facility_id'],Money::fromDecimal($_POST['amount']??''),$_POST['idempotency_key']??'');$success='Repayment completed. Reference '.$result['reference'].'.';}}catch(Throwable $e){$error=$e->getMessage();}}
$eligibility=$service->eligibility($customerId);$apps=$pdo->prepare('SELECT * FROM credit_applications WHERE user_id=? ORDER BY created_at DESC');$apps->execute([$customerId]);$applications=$apps->fetchAll();$fac=$pdo->prepare('SELECT * FROM credit_facilities WHERE user_id=? ORDER BY disbursed_at DESC');$fac->execute([$customerId]);$facilities=$fac->fetchAll();
?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif?><div class="app-grid"><section class="panel span-5"><h2>Visa eligibility</h2><span class="badge <?=$eligibility['eligible']?'eligible':'pending'?>"><?=$eligibility['eligible']?'eligible':'not eligible'?></span><?php if(!$eligibility['eligible']):?><ul><?php foreach($eligibility['reasons'] as $reason):?><li><?=e($reason)?></li><?php endforeach?></ul><?php else:?><p class="muted">Configured maximum: <?=Money::format($eligibility['maximum_cents'],true)?>. Final approval requires review.</p><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="apply"><div class="field full"><label for="amount">Requested amount (USD)</label><input id="amount" name="amount" inputmode="decimal" required></div><div class="field full"><label for="term_months">Term</label><select id="term_months" name="term_months"><?php foreach($eligibility['allowed_terms'] as $term):?><option value="<?=$term?>"><?=$term?> months</option><?php endforeach?></select></div><div class="field full"><label for="purpose">Purpose</label><textarea id="purpose" name="purpose" maxlength="255" required></textarea></div><div class="field full"><button class="button button-primary">Submit application</button></div></form><?php endif?></section><section class="panel span-7"><h2>Applications</h2><?php if(!$applications):?><div class="empty">No applications.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Requested</th><th>Approved</th><th>Term</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($applications as $a):?><tr><td><?=e($a['application_id'])?></td><td><?=Money::format((int)$a['requested_amount_cents'])?></td><td><?=$a['approved_amount_cents']!==null?Money::format((int)$a['approved_amount_cents']):'—'?></td><td><?=e($a['term_months'])?> mo</td><td><span class="badge <?=e($a['status'])?>"><?=e(str_replace('_',' ',$a['status']))?></span></td><td><?php if($a['status']==='approved'):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="accept"><input type="hidden" name="application_id" value="<?=e($a['application_id'])?>"><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(24)))?>"><button class="button button-primary">Accept terms</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><?php foreach($facilities as $facility):?><section class="panel span-12"><h2>Facility <?=e($facility['reference'])?></h2><div class="app-grid"><div class="span-4"><span class="muted">Outstanding</span><div class="stat-value"><?=Money::format((int)$facility['outstanding_cents'])?></div></div><div class="span-4"><span class="muted">Principal</span><div class="stat-value"><?=Money::format((int)$facility['principal_cents'])?></div></div><div class="span-4"><span class="muted">Status</span><div><span class="badge <?=e($facility['status'])?>"><?=e($facility['status'])?></span></div></div></div><?php if($facility['status']==='active'):?><form method="post" class="form-grid" style="margin-top:20px"><?=csrfField()?><input type="hidden" name="action" value="repay"><input type="hidden" name="facility_id" value="<?=e($facility['facility_id'])?>"><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(24)))?>"><div class="field"><label>Repayment amount (USD)</label><input name="amount" inputmode="decimal" required></div><div class="field" style="align-self:end"><button class="button button-primary">Make repayment</button></div></form><?php endif?></section><?php endforeach?></div><?php require __DIR__.'/../includes/customer_footer.php';?>
